using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Restore EF8 behavior so existing 500K docs with "Discriminator" still work.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 breaking change: id format changed from "EntityName|KeyValue" to just "KeyValue".
            // Restore EF8 format so existing docs with "Product|123" ids are found.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            entity.HasIndex(p => p.Sku);
        });
    }
}

